        let is_valid = self.validate_session(session_id).await?;

        Ok(json!({
            "valid": is_valid,
            "session_id": session_id
290→        }))
    }

    /// Handle D-Bus method call for getting client capabilities
    pub async fn dbus_get_capabilities(&self, session_id: &str) -> Result<Value> {
        let capabilities = self.get_client_capabilities(session_id).await?;

        Ok(json!({
            "capabilities": capabilities,
            "session_id": session_id
300→        }))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn supplied_peer_key_or_wristband_cannot_select_full_access_route() {
310→        // The production route_client path uses this same decision function.
        // No plaintext key storage is constructed to test legacy denial.
        let peer_key = hex::encode([7_u8; 32]);
        let wristband = Uuid::new_v4().to_string();

